    $colors = (new App\Support\XlsxFillColorReader())->read($file, $sheet, "B");
    echo "$sheet: "; var_export($colors); echo "\n";
}'

docker exec atmosphera-hub_php php artisan tinker --execute='
use AtrioTeam\DigitalHub\Tags\Models\TagGroup;
TagGroup::query()->whereIn("entity_type", ["fabric","material"])->where("category_1_id", App\Models\Category1::where("slug","outdoor")->value("id"))->with("categories.tags")->get()->each(function ($g) {
    echo "== ".$g->getTranslation("name","it")." (".$g->entity_type.")\n";
    foreach ($g->categories as $c) {
        echo "  [".$c->slug."] ".$c->tags->map(fn($t) => $t->getTranslation("name","it").($t->color ? " ".$t->color : ""))->implode(" | ")."\n";
    }
});' 2>&1
